import{d as u,C as t,o as c,c as b,j as a,a as o,E as r,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const w=JSON.parse('{"title":"道德经第四十八章","description":"比较为学日益与为道日损，理解返虚、无为及无事取天下。","frontmatter":{"title":"道德经第四十八章","description":"比较为学日益与为道日损，理解返虚、无为及无事取天下。","category":"guide","aliases":["道德经第四十八章","老子第四十八章","dao de jing chapter 48"],"source":["王弼《道德真经注》卷三"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-48.md","filePath":"daoism/dao-de-jing/chapter-48.md","lastUpdated":1794189804000}'),p={name:"daoism/dao-de-jing/chapter-48.md"},_=u({...p,setup(x){const n=[{id:"learning-and-dao",label:"为学日益，为道日损",showLabel:!0,sentences:[[{text:"为学",glossary:"weixue"},"日益，",{text:"为道",glossary:"weidao"},"日",{text:"损",glossary:"sun"},"。"]],note:["【白话】从事学问，所知所能日益增加；行道的工夫，则朝着日益减损的方向。二者所指的工夫不同，不能只用增加多少来衡量。","【王弼注择要】为学下注「务欲进其所能，益其所习」；为道下注「务欲反虚无也」，以增加能力、习得与返于虚无作对照。","【读法】依返虚读日损，可从减去执定与刻意造作来理解，不是删去已经学会的知识和能力。所据录文此处作曰损，本站保留日损，差异在篇末列明。"]},{id:"repeated-reduction",label:"损之又损",showLabel:!0,sentences:[[{text:"损",glossary:"sun"},"之又",{text:"损",glossary:"sun"},"，以至于",{text:"无为",glossary:"wuwei"},"。"]],note:["【白话】继续减损，再继续减损，直到不再以自己的私意妄加造作。减损指向无为，而非以少为终点。","【读法】所据录文此句未另见独立王注，可连上一段返虚之注与下一段无为之用理解。每次所损为何，应放回是否执定一形、妨碍事物成全来判断。","【读法】损之又损不是对资源、知识、责任一概减到没有；若减去的是事情成立的必要条件，便不能只凭变少自称合道。"]},{id:"nonaction-and-completion",label:"无为而无不为",showLabel:!0,sentences:[[{text:"无为",glossary:"wuwei"},"而",{text:"无不为",glossary:"wubuwei"},"。"]],note:["【白话】不妄作，却使事物无不得到成就。这里的无不为承接无为的作用，不等于自己必须亲手做完所有事情。","【王弼注择要】「有为则有所失，故无为乃无所不为也。」注从强作可能有所偏失，说明不固执己意才不致遗漏成物的可能。","【读法】这与第三十七章呼应。无不为是章内成用的表达，不是宣称无需条件即可获得任何结果；仍须辨明哪些行动顺应事情的实际需要。"]},{id:"governing-without-invented-interference",label:"取天下常以无事",showLabel:!0,sentences:[[{text:"取",glossary:"qu"},"天下常以",{text:"无事",glossary:"wushi"},"，及其",{text:"有事",glossary:"youshi"},"，不足以",{text:"取",glossary:"qu"},"天下。"]],note:["【白话】治理、持守天下，常要以不妄造事端为原则；等到只凭自己不断造事，便不足以治理天下了。","【王弼注择要】无事下注「动常因也」；有事下注「自已造也」；不足以取天下下注「失统本也」。本页保留第二处录文的自已字样，不擅改后当作原引。","【读法】取天下在这里落到治理与持守，王弼以能否统本说明。无事、有事重在因物与自造的分别，不按事务数量判断，也不取消日常维护、应急和照料。"]}],s=[{id:"weixue",term:"为学",sense:1},{id:"weidao",term:"为道",sense:1},{id:"sun",term:"损",sense:1},{id:"wuwei",term:"无为",sense:1},{id:"wubuwei",term:"无不为",sense:1},{id:"qu",term:"取",sense:1},{id:"wushi",term:"无事",sense:1},{id:"youshi",term:"有事",sense:1}];return(g,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return c(),b("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第四十八章",tabindex:"-1"},[o("道德经第四十八章 "),a("a",{class:"header-anchor",href:"#道德经第四十八章","aria-label":'Permalink to "道德经第四十八章"'},"​")],-1)),r(i,{title:"为学在增加，为道为什么反而要减损",summary:"本章先比较为学与为道，再把日损推进到无为，最后落到取天下的无事与有事。王弼以增进所能、返于虚无解释益损，以因物与自造解释无事、有事，重点在成用而非一味减少。",points:[{label:"先读",text:"为学之益写所能所习的增加，为道之损写返虚的方向，不能混成停止学习。"},{label:"再辨",text:"无为与无不为相连，不是个人必须包办一切，也不是所有事情都任其自流。"},{label:"后看",text:"无事循动常因解释，有事循自己造作解释，不按忙闲多少判断。"}],hint:"为学、为道的为读 wéi；损为减损，无事在这里是少造事端、因物而行，不是无人需要照料。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[o("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),r(l,{sections:n,glossary:s}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[o("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"为学日益，为道日损。",tone:"两种工夫的方向",guide:"增进所能所习与返于虚无各有所指，不能只比较数量。"},{text:"损之又损，以至于无为。无为而无不为。",tone:"减损须指向成用",guide:"损去妄作而让事物成就，不以少做、少知本身为目标。"},{text:"取天下常以无事，及其有事，不足以取天下。",tone:"因物还是自造",guide:"以动常因与自己造作的分别读无事、有事，落到治理的根本。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[o("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),r(h,{items:s}),e[4]||(e[4]=m('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-本章从个人工夫怎样转到天下" tabindex="-1">象：本章从个人工夫怎样转到天下？ <a class="header-anchor" href="#象-本章从个人工夫怎样转到天下" aria-label="Permalink to &quot;象：本章从个人工夫怎样转到天下？&quot;">​</a></h3><p>先说学与道的益损，再以无为而无不为说明作用，最后把因物、不自造的原则放进天下治理。工夫与治理由成用贯通，而非各说一种消极退缩。</p><h3 id="理-为什么越用力增加-仍可能有所失" tabindex="-1">理：为什么越用力增加，仍可能有所失？ <a class="header-anchor" href="#理-为什么越用力增加-仍可能有所失" aria-label="Permalink to &quot;理：为什么越用力增加，仍可能有所失？&quot;">​</a></h3><p>若新增的规定与手段只延伸自己的预设，就可能顾此失彼。王弼的有为则有所失提醒人检查造作的限度，而非否定能力增长与必要行动。</p><h3 id="用-今天怎样判断一项事务应当增还是减" tabindex="-1">用：今天怎样判断一项事务应当增还是减？ <a class="header-anchor" href="#用-今天怎样判断一项事务应当增还是减" aria-label="Permalink to &quot;用：今天怎样判断一项事务应当增还是减？&quot;">​</a></h3><p>先辨它解决什么实际需要，再看新增流程是否确实改善结果。能成全事情的能力应当保留，只为显示控制、制造负担的部分才值得减去。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>学习可以增加，执定可以减少。</strong> 掌握更多方法，不必把某一个方法变成永远不能改变的标准。能力的增加与对单一形式的松开，可以同时发生。</p><p><strong>减少为了管理而制造的事务。</strong> 检查报告、会议与审批是否仍有明确用途。无事的启发在于让事情按其条件运行，而不是省掉必要的沟通、维护与负责。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我想减掉的，是妄作与执定，还是事情真正需要的能力和责任？新增一项流程之前，我能否说清它服务什么实际需要？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文与标点沿本站保留，据卷三 009b–010a 电子录文核对。本站为道日损的日，录文作曰，保留并注明，不据此另造解释。</li><li>无事、有事依王注因物与自造释读；所据有事下注作自已造也，本页引用保留该字样，解释用自己造作说明。</li><li>为学与为道的白话分别交代增能、返虚；不以日损直接主张反知识或普遍削减。现代流程整理属于本站类比。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_003.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷三 HFL 本电子录文，009b–010a</a>。</p>',15))])}}});export{w as __pageData,_ as default};
